// The SDK is loaded as browser ESM. No signing keys are stored by this app.
const CONTRACT = '0x2e1C4151d932a8d74854B86dEb03f7191F2332d8';
const EXPLORER = 'https://explorer-studio.genlayer.com';
let sdk, chain, reader, account = null, job = null, busy = false;
const $ = id => document.getElementById(id);
const safe = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(message, isError = false, link) { const n = $('notice'); n.hidden = false; n.className = isError ? 'error' : ''; n.innerHTML = safe(message) + (link ? ` <a href="${safe(link)}" target="_blank" rel="noopener">View transaction ↗</a>` : ''); }
function tab(name) { for (const id of ['open','create']) $(id).hidden = id !== name; document.querySelectorAll('.tab').forEach(el => el.classList.toggle('active',el.dataset.target===name)); }
document.querySelectorAll('[data-target]').forEach(button => button.addEventListener('click', () => { tab(button.dataset.target); $('workspace').scrollIntoView({behavior:'smooth'}); }));
async function client() { if (!reader) { const [s,c] = await Promise.all([import('https://esm.sh/genlayer-js@1.1.8?bundle'),import('https://esm.sh/genlayer-js@1.1.8/chains?bundle')]); sdk=s; chain=c.studionet; reader=s.createClient({chain}); } return reader; }
async function connect() { if (!window.ethereum) throw new Error('Install a browser wallet to create or update an assignment.'); const accounts=await window.ethereum.request({method:'eth_requestAccounts'}); if (!accounts[0]) throw new Error('Wallet connection was cancelled.'); account=accounts[0]; $('connect').textContent=account.slice(0,6)+'…'+account.slice(-4); await client(); const writer=sdk.createClient({chain,account,provider:window.ethereum}); await writer.connect('studionet'); return writer; }
$('connect').addEventListener('click',()=>connect().then(()=>notice('Wallet connected to Studionet.')).catch(e=>notice(e.shortMessage||e.message,true)));
if(window.ethereum?.on){window.ethereum.on('accountsChanged',accounts=>{account=accounts[0]||null; $('connect').textContent=account?account.slice(0,6)+'…'+account.slice(-4):'Connect wallet';});window.ethereum.on('chainChanged',()=>notice('Wallet network changed. Connect to Studionet before sending a transaction.'));}
async function write(method,args){if(busy)throw Error('A transaction is already in progress.');busy=true;try{const writer=await connect(); notice('Confirm the transaction in your wallet.'); const hash=await writer.writeContract({address:CONTRACT,functionName:method,args,value:0n,leaderOnly:false}); const link=`${EXPLORER}/tx/${hash}`; notice('Transaction submitted. Waiting for consensus…',false,link); const started=Date.now(); while(Date.now()-started<120000){await new Promise(resolve=>setTimeout(resolve,5000));try{const tx=await reader.getTransaction({hash});const status=String(tx.statusName||tx.status||'pending');const outcome=String(tx.txExecutionResultName||tx.tx_execution_result_name||'');const consensus=String(tx.result_name||tx.resultName||'');const leader=tx.consensus_data?.leader_receipt;const leaderError=leader?.execution_result==='ERROR'||leader?.result?.status==='rollback';notice(`Transaction status: ${status}${consensus?' · '+consensus:''}`,false,link);if(/ERROR|FAILED|REJECTED|CANCELED|CANCELLED/i.test(status+' '+outcome)||(status==='FINALIZED'&&(consensus==='MAJORITY_DISAGREE'||leaderError))){notice('Transaction failed or validators did not reach agreement. No result was saved; inspect the explorer before trying again.',true,link);return {hash,success:false}}if(status==='FINALIZED'){const success=consensus==='MAJORITY_AGREE'&&!leaderError;if(success)notice('Transaction finalized with validator agreement. Refresh the assignment to see its current state.',false,link);else notice('Transaction finalized, but execution could not be confirmed. Inspect the explorer before retrying.',true,link);return {hash,success}}}catch{/* Continue polling; the explorer link remains available. */}}notice('Still waiting for a final result. Check the transaction in the explorer before retrying.',false,link);return {hash,success:false}}finally{busy=false} }
async function readJob(id) {const c=await client();const raw=await c.readContract({address:CONTRACT,functionName:'get_job',args:[BigInt(id)]});return typeof raw==='string'?JSON.parse(raw):raw;}
const segments = value => Object.entries(value||{}).map(([k,v])=>`<div><b>${safe(k)}</b><p>${safe(v)}</p></div>`).join('') || '<p>Nothing submitted yet.</p>';
function paintJob(id) {const j=job; const view=$('job-view'); view.hidden=false;const flags=j.report?.findings||[];const report=flags.length?flags.map(x=>`${x.segment}: ${x.code}${x.term ? ' — '+x.term : ''}`).join('\n'):(j.report?.passed?'No issues reported.':'No evaluation yet.');view.innerHTML=`<div class="job-title"><h3>Assignment #${safe(id)}</h3><span class="pill ${j.status==='ACCEPTED'?'green':j.status==='REVISION_REQUIRED'?'amber':''}">${safe(j.status.replaceAll('_',' '))}</span></div><div class="job-metadata">Client: ${safe(j.client)}<br>Translator: ${safe(j.translator)}<br>${safe(j.rules.source_language)} → ${safe(j.rules.target_language)} · Attempt ${safe(j.attempt)} / ${safe(j.max_attempts)}<br>Audience: ${safe(j.rules.audience)} · Style: ${safe(j.rules.style)}</div><div class="review-grid"><div class="review-box"><h4>SOURCE TEXT</h4>${segments(j.source)}</div><div class="review-box"><h4>LATEST TRANSLATION</h4>${segments(j.delivery)}</div></div><div class="report"><strong>Review:</strong> ${safe(report)}</div><div id="job-action-area"></div><details class="history"><summary>View evaluated attempts</summary><div id="history-content"><p>Loading on-chain history…</p></div></details>`; const area=$('job-action-area'); if(['OPEN','REVISION_REQUIRED'].includes(j.status)){area.innerHTML=`<label>Translation<textarea id="delivery" placeholder="Enter your translation…"></textarea></label><p class="hint">Only the assigned translator can submit. A revised version must change the previous delivery.</p><div class="job-actions"><button id="submit-delivery" class="button dark">Submit translation ↗</button>${j.status==='OPEN'?'<button id="cancel-job" class="button outline">Cancel assignment</button>':''}<button id="abandon-job" class="button outline">Abandon assignment</button></div>`; $('submit-delivery').onclick=async()=>{try{const keys=Object.keys(j.source);if(keys.length!==1)throw Error('This workspace supports submissions to single-segment assignments only.');const text=$('delivery').value;if(!text.trim())throw Error('Enter a translation first.');await write('submit',[BigInt(id),JSON.stringify({[keys[0]]:text})]);}catch(e){notice(e.shortMessage||e.message,true)}};if($('cancel-job'))$('cancel-job').onclick=()=>write('cancel',[BigInt(id)]).catch(e=>notice(e.shortMessage||e.message,true));$('abandon-job').onclick=()=>write('abandon',[BigInt(id)]).catch(e=>notice(e.shortMessage||e.message,true));}else if(j.status==='SUBMITTED'){area.innerHTML='<div class="job-actions"><button id="evaluate-job" class="button dark">Request evaluation ↗</button></div><p class="hint">Anyone can request an evaluation. Validator consensus may take time.</p>';$('evaluate-job').onclick=()=>write('evaluate',[BigInt(id)]).catch(e=>notice(e.shortMessage||e.message,true));} loadHistory(id,j.attempt);}
async function loadHistory(id,count){const box=$('history-content');if(!count){box.innerHTML='<p>No evaluated attempts yet.</p>';return;} const c=await client(); const rows=[];for(let n=1;n<=count;n++){try{const raw=await c.readContract({address:CONTRACT,functionName:'get_attempt',args:[BigInt(id),BigInt(n)]});const attempt=typeof raw==='string'?JSON.parse(raw):raw;rows.push(`<pre>${safe(JSON.stringify(attempt,null,2))}</pre>`)}catch{rows.push(`<p>Attempt ${n} has not been evaluated or is unavailable.</p>`)}}if(box.isConnected)box.innerHTML=rows.join('');}
$('open-form').addEventListener('submit',async e=>{e.preventDefault();try{notice('Reading assignment from Studionet…');const id=$('job-id').value;job=await readJob(id);paintJob(id);notice(`Assignment #${id} loaded from Studionet.`)}catch(err){$('job-view').hidden=true;notice('Could not load this assignment. The network may be unavailable or Studionet state may have reset. '+(err.shortMessage||err.message),true)}});
$('create-form').addEventListener('submit',async e=>{e.preventDefault();try{const source=$('source').value;if(!source.trim())throw Error('Enter source text.');const rules={source_language:$('source-lang').value,target_language:$('target-lang').value,audience:$('audience').value,style:$('style').value,glossary:[],forbidden_terms:[]};const c=await client();const before=BigInt(await c.readContract({address:CONTRACT,functionName:'get_next_id',args:[]}));const result=await write('create_job',[$('translator').value,JSON.stringify({text:source}),JSON.stringify(rules),BigInt($('attempts').value)]);if(result.success){const after=BigInt(await c.readContract({address:CONTRACT,functionName:'get_next_id',args:[]}));let found=null;for(let id=before;id<after && id<before+30n;id++){const candidate=await readJob(id);if(candidate.client.toLowerCase()===account.toLowerCase()&&candidate.translator.toLowerCase()===$('translator').value.toLowerCase()&&candidate.source.text===source&&candidate.attempt===0){found=id;break}}if(found!==null){$('job-id').value=String(found);job=await readJob(found);tab('open');paintJob(found);notice(`Assignment #${found} created. Share this ID with the translator.`,false,`${EXPLORER}/tx/${result.hash}`)}else notice('Transaction finalized. Find the assignment ID in the explorer before continuing.',false,`${EXPLORER}/tx/${result.hash}`)}}catch(err){notice(err.shortMessage||err.message,true)}});
function example(){tab('open');$('job-id').value='1';$('workspace').scrollIntoView({behavior:'smooth'});$('open-form').requestSubmit();} $('load-example').onclick=example;$('example-inline').onclick=example;

